<?php
declare(strict_types=1);

function nzasec_account_blocked(array $db,string $uid): bool {return nzc_user_blocked($db,$uid);}
function nzasec_risk(array $db,string $uid): array {
    $score=0;$reasons=[];$rejected=0;$flaggedPosts=0;$reports=0;$dup=0;$messages=0;
    foreach($db['posts']??[]as$p)if(($p['user_id']??'')===$uid){if(($p['status']??'')==='rejected')$rejected++;if(!empty($p['moderation']['flagged']))$flaggedPosts++;}
    foreach($db['reports']??[]as$r){if(($r['reported_user_id']??'')===$uid)$reports++;if(($r['reporter_id']??'')==='system-duplicate'&&($r['details']??'')!==''&&($r['user_id']??'')===$uid)$dup++;if(($r['reported_user_id']??'')===$uid&&str_contains((string)($r['reason']??''),'پیام'))$messages++;}
    $score=min(100,$rejected*12+$flaggedPosts*18+$reports*16+$dup*30+$messages*20);if($rejected)$reasons[]=$rejected.' آگهی ردشده';if($flaggedPosts)$reasons[]=$flaggedPosts.' آگهی علامت‌گذاری‌شده';if($reports)$reasons[]=$reports.' گزارش علیه کاربر';if($dup)$reasons[]=$dup.' تلاش تکراری';if($messages)$reasons[]=$messages.' پیام پرریسک';return['score'=>$score,'reasons'=>$reasons];
}
function nzasec_handle_post(string $action): never {
    nzc_session_open();$db=nzc_db_read();$admin=nzc_require_admin($db);if(!nzc_csrf_valid())throw new RuntimeException('درخواست نامعتبر است.');$uid=trim((string)($_POST['user_id']??''));if($uid===''||$uid===$admin['id'])throw new RuntimeException('کاربر انتخاب‌شده معتبر نیست.');$exists=false;foreach($db['users']as$u)if(($u['id']??'')===$uid){$exists=true;break;}if(!$exists)throw new RuntimeException('کاربر پیدا نشد.');$reason=mb_substr(trim((string)($_POST['reason']??'')),0,500);
    if($action==='admin_block_user'){
        nzc_db_write(function(&$db)use($uid,$admin,$reason){$updated=false;foreach($db['blocks']??[]as&$b)if(($b['user_id']??'')===$uid){$b['status']='active';$b['reason']=$reason!==''?$reason:'تصمیم مدیر امنیت';$b['updated_at']=nzc_now();$b['admin_id']=$admin['id'];$updated=true;break;}unset($b);if(!$updated)$db['blocks'][]=['id'=>nzc_uid('ban'),'user_id'=>$uid,'status'=>'active','reason'=>$reason!==''?$reason:'تصمیم مدیر امنیت','admin_id'=>$admin['id'],'created_at'=>nzc_now()];nzc_support_message($db,$uid,'حساب شما موقتاً برای بررسی امنیتی محدود شده است. برای پیگیری با پشتیبانی گفتگو کنید.');nzc_notify($db,$uid,'حساب شما برای بررسی امنیتی محدود شده است.','high');});nzc_audit($admin,'admin_block_user','user',$uid,['reason'=>$reason]);nzc_flash('حساب کاربر محدود شد.','ok');nzc_redirect('/nz?page=admin#risk-users');
    }
    if($action==='admin_unblock_user'){
        nzc_db_write(function(&$db)use($uid,$admin){foreach($db['blocks']??[]as&$b)if(($b['user_id']??'')===$uid){$b['status']='inactive';$b['updated_at']=nzc_now();$b['unblocked_by']=$admin['id'];}unset($b);nzc_support_message($db,$uid,'محدودیت امنیتی حساب شما برداشته شد.');nzc_notify($db,$uid,'محدودیت حساب برداشته شد.');});nzc_audit($admin,'admin_unblock_user','user',$uid);nzc_flash('محدودیت حساب برداشته شد.');nzc_redirect('/nz?page=admin#risk-users');
    }
    throw new RuntimeException('عملیات مدیریتی معتبر نیست.');
}
function nzasec_recent_audit(int $limit=50): array {
    $pdo=nzstore_sqlite();if(!$pdo)return[];try{$st=$pdo->prepare('SELECT actor_id,action,target_type,target_id,ip,payload,created_at FROM nz_audit ORDER BY id DESC LIMIT ?');$st->bindValue(1,max(1,min(200,$limit)),PDO::PARAM_INT);$st->execute();return$st->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable $e){return[];}
}
function nzasec_admin_html(array $db): string {
    $rows=[];foreach($db['users']??[]as$u){if(nzc_is_admin($u))continue;$risk=nzasec_risk($db,(string)($u['id']??''));if($risk['score']<12&&!nzasec_account_blocked($db,(string)$u['id']))continue;$rows[]=['user'=>$u,'risk'=>$risk];}usort($rows,fn($a,$b)=>(int)$b['risk']['score']<=>(int)$a['risk']['score']);$csrf=nzc_e($_SESSION['csrf']??'');$h='<section class="surface" id="risk-users"><h2>کاربران پرریسک و محدودیت حساب</h2>';
    if(!$rows)$h.='<div class="empty">کاربر پرریسک فعالی وجود ندارد.</div>';foreach(array_slice($rows,0,60)as$row){$u=$row['user'];$risk=$row['risk'];$uid=(string)$u['id'];$blocked=nzasec_account_blocked($db,$uid);$h.='<article class="nzasec-user"><div><b>'.nzc_e($u['name']??'کاربر نیازستان').' · <span dir="ltr">'.nzc_e($u['phone']??'').'</span></b><small>ریسک '.$risk['score'].'/100 · '.nzc_e(implode('، ',$risk['reasons'])).'</small><small>IP: <span dir="ltr">'.nzc_e($u['last_ip']??'ثبت نشده').'</span> · '.nzc_e($u['last_device']??'دستگاه ثبت نشده').'</small></div><form method="post"><input type="hidden" name="csrf" value="'.$csrf.'"><input type="hidden" name="action" value="'.($blocked?'admin_unblock_user':'admin_block_user').'"><input type="hidden" name="user_id" value="'.nzc_e($uid).'">'.(!$blocked?'<input name="reason" maxlength="500" placeholder="دلیل محدودسازی">':'').'<button class="btn '.($blocked?'primary':'danger').'">'.($blocked?'رفع محدودیت':'محدودکردن حساب').'</button></form></article>';}
    $h.='</section><section class="surface"><h2>آخرین رویدادهای مدیریتی و امنیتی</h2>';$audit=nzasec_recent_audit();if(!$audit)$h.='<div class="empty">هنوز رویداد Audit ثبت نشده است.</div>';foreach($audit as$a){$payload=json_decode((string)($a['payload']??''),true);$h.='<div class="nzasec-audit"><b>'.nzc_e($a['action']??'رویداد').'</b><span>'.nzc_e(($a['target_type']??'').' '.($a['target_id']??'')).' · '.nzc_e(date('Y/m/d H:i',strtotime($a['created_at']??'now'))).'</span>'.(!empty($payload)?'<small>'.nzc_e(mb_substr(json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?:'',0,300)).'</small>':'').'</div>';}
    return$h.'</section>';
}
function nzasec_enhance(string $html): string {
    if(($_GET['page']??'')!=='admin')return$html;nzc_session_open();$db=nzc_db_read();$u=nzc_current_user($db);if(!$u||!nzc_is_admin($u))return$html;$extra=nzasec_admin_html($db);$html=str_replace('</main>',$extra.'</main>',$html);$css='<style id="nzasec-style">.nzasec-user{display:grid;grid-template-columns:1fr minmax(260px,.8fr);gap:10px;align-items:center;padding:12px 0;border-top:1px solid #eceef1}.nzasec-user small{display:block;color:#747b84;margin-top:5px}.nzasec-user form{display:flex;gap:6px}.nzasec-user input{flex:1;border:1px solid #dfe2e6;border-radius:10px;padding:9px;font:inherit}.nzasec-audit{padding:9px 0;border-top:1px solid #eee}.nzasec-audit b,.nzasec-audit span,.nzasec-audit small{display:block}.nzasec-audit span,.nzasec-audit small{color:#747b84;margin-top:3px;font-size:11px}@media(max-width:720px){.nzasec-user{grid-template-columns:1fr}.nzasec-user form{flex-direction:column}}</style>';return str_replace('</head>',$css.'</head>',$html);
}
